    TreeNode* deserialize(string data) {
        vector<int> result;
        TreeNode* root = nullptr;
        for (char c : data) {
            result.push_back(c - '0');
        }
        dfs(result[0], root);
        return root;

        void dfs(int val, TreeNode*& root) {
            if (val == 0) {
                return;
            }
            TreeNode* node = new TreeNode(val);
            dfs(result[1], node->left);
            dfs(result[2], node->right);
            root->left = node;
            delete node;
        }
    }
};

