        int moves = 0;
        int len = s.length();
        for (int i = 0; i < len / 2; i++) {
            if (s.charAt(i) != s.charAt(len - 1 - i)) {
                s = swapCharacters(s, i, len - 1 - i);
                moves++;
            }
        }
        return moves;
    }

    private String swapCharacters(String s, int i, int j) {
        char temp = s.charAt(i);
        s.setCharAt(i, s.charAt(j));
        s.setCharAt(j, temp);
        return s;
    }
}

