                String prefix = parts[i].substring(0, k);
                String suffix = parts[i].substring(parts[i].length() - k);
                result.append(prefix).append(parts[i]).append(suffix);
            }
        }

        result.insert(0, "-");
        result.insert(result.length() - 1, "-");

        return result.toString().toUpperCase();
    }
}

