        vector<vector<int>> red(n), blue(n);
        for (auto& e : redEdges) red[e[0]].push_back(e[1]);
        for (auto& e : blueEdges) blue[e[0]].push_back(e[1]);

        vector<vector<int>> dist(n, vector<int>(2, -1));
        vector<int> ans(n, -1);
        ans[0] = 0;

        queue<tuple<int, int, int>> q;
        for (int v : red[0]) {
            if (dist[v][0] == -1) {
                dist[v][0] = 1;
                q.push({v, 0, 1});
            }
        }
        for (int v : blue[0]) {
            if (dist[v][1] == -1) {
                dist[v][1] = 1;
                q.push({v, 1, 1});
            }
        }

        while (!q.empty()) {
            auto [u, c, d] = q.front();
            q.pop();
            if (c == 0) {
                for (int v : blue[u]) {
                    if (dist[v][1] == -1 || dist[v][1] > d + 1) {
                        dist[v][1] = d + 1;
                        q.push({v, 1, d + 1});
