class Solution {
public:
    long long mostPoints(vector<vector<int>>& questions) {
        int n = questions.size();
        if (n == 0) return 0;
        vector<long long> dp(n + 1, 0);
        for (int i = n - 1; i >= 0; --i) {
            int points = questions[i][0];
            int b = questions[i][1];
            int next_i = i + b + 1;
            long long option1;
            if (next_i >= n) {
                option1 = points;
            } else {
                option1 = points + dp[next_i];
            }
            long long option2 = dp[i + 1];
            dp[i] = max(option1, option2);
        }
        return dp[0];
    }
};

