        for (char c : word) {
            freq[c - 'a']++;
        }

        for (int i = 0; i < 26; ++i) {
            if (freq[i] == 0) continue;

            vector<int> temp;
            for (int j = 0; j < 26; ++j) {
                if (j == i) {
                    if (freq[j] == 1) {
