        vector<int> result;
        for (int i : A) {
            int left = i - k;
            int right = i + k;
            auto it = lower_bound(B.begin(), B.end(), left);
            if (it != B.end() && *it <= right) {
                result.push_back(i);
            }
        }
        return result;
