private:
    static vector<int> computeLPS(const string& pattern) {
        int m = pattern.size();
        vector<int> lps(m, 0);
        int length = 0;
        for (int i = 1; i < m; ++i) {
            while (length > 0 && pattern[i] != pattern[length]) {
                length = lps[length - 1];
            }
            if (pattern[i] == pattern[length]) {
                length++;
                lps[i] = length;
            } else {
                lps[i] = 0;
            }
        }
        return lps;
    }

