        vector<int> occurrences;
        int n = text.size();
        int m = pattern.size();
        if (m == 0 || n < m) return occurrences;

        vector<int> lps = computeLPS(pattern);
        int i = 0, j = 0;
        while (i < n) {
            if (text[i] == pattern[j]) {
                i++;
                j++;
                if (j == m) {
                    occurrences.push_back(i - j);
                    j = lps[j - 1];
                }
            } else {
                if (j != 0) {
                    j = lps[j - 1];
                } else {
                    i++;
                }
            }
        }
        return occurrences;
    }
};

