                upgrades_used += cost;
                edges_added++;

                if (edges_added == c - 1) {
                    break;
                }
            }
        }

        return edges_added == c - 1 && upgrades_used <= k;
    }

    class DSU {
    private:
        vector<int> parent;
        vector<int> rank;
        int components;

    public:
        DSU(int n) {
            parent.resize(n);
            rank.resize(n, 0);
            components = n;
            for (int i = 0; i < n; ++i) {
                parent[i] = i;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        void union_nodes(int x, int y) {
            int x_root = find(x);
            int y_root = find(y);
            if (x_root == y_root) {
                return;
            }
            if (rank[x_root] < rank[y_root]) {
                parent[x_root] = y_root;
            } else {
                parent[y_root] = x_root;
                if (rank[x_root] == rank[y_root]) {
                    rank[x_root]++;
                }
            }
            components--;
        }

        int count_components() {
            return components;
        }
    };
};

