class Solution {
    public int maxAbsValExpr(int[] arr1, int[] arr2) {
        int max1 = Integer.MIN_VALUE, min1 = Integer.MAX_VALUE;
        int max2 = Integer.MIN_VALUE, min2 = Integer.MAX_VALUE;
        int max3 = Integer.MIN_VALUE, min3 = Integer.MAX_VALUE;
        int max4 = Integer.MIN_VALUE, min4 = Integer.MAX_VALUE;

        for (int i = 0; i < arr1.length; i++) {
            int t1 = arr1[i] + arr2[i] + i;
            int t2 = arr1[i] - arr2[i] + i;
            int t3 = -arr1[i] + arr2[i] + i;
            int t4 = -arr1[i] - arr2[i] + i;

            max1 = Math.max(max1, t1);
            min1 = Math.min(min1, t1);

            max2 = Math.max(max2, t2);
            min2 = Math.min(min2, t2);

            max3 = Math.max(max3, t3);
            min3 = Math.min(min3, t3);

            max4 = Math.max(max4, t4);
            min4 = Math.min(min4, t4);
        }

        int diff1 = max1 - min1;
        int diff2 = max2 - min2;
        int diff3 = max3 - min3;
        int diff4 = max4 - min4;

        return Math.max(Math.max(diff1, diff2), Math.max(diff3, diff4));
    }
}

