class Solution {
    public String reverseParentheses(String s) {
        Deque<Integer> stack = new ArrayDeque<>();
        List<int[]> pairs = new ArrayList<>();

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '(') {
                stack.push(i);
            } else if (c == ')') {
                if (!stack.isEmpty()) {
                    int level = stack.size();
                    int start = stack.pop();
                    pairs.add(new int[]{start, i, level});
                }
            }
        }

        pairs.sort((a, b) -> Integer.compare(b[2], a[2]));

        char[] arr = s.toCharArray();

        for (int[] pair : pairs) {
            int start = pair[0];
            int end = pair[1];
            int left = start + 1;
            int right = end - 1;
            while (left < right) {
                char temp = arr[left];
                arr[left] = arr[right];
                arr[right] = temp;
                left++;
                right--;
            }
        }

        return new String(arr);
    }
}

