            if (secretTime[x] <= t || secretTime[y] <= t) {
                if (secretTime[x] > t) {
                    secretTime[x] = t;
                }
                if (secretTime[y] > t) {
                    secretTime[y] = t;
                }
            }
        }

        List<Integer> result = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (secretTime[i] != Integer.MAX_VALUE) {
                result.add(i);
            }
        }
        return result;
    }
}

