class Solution {
    public long repairCars(int[] ranks, int cars) {
        Arrays.sort(ranks);
        int n = ranks.length;
        int maxRank = ranks[n - 1];
        long low = 0;
        long high = (long) maxRank * cars * cars;

        while (low < high) {
            long mid = low + (high - low) / 2;
            long sum = 0;
            for (int r : ranks) {
                long maxCars = (long) Math.sqrt(mid / r);
                sum += maxCars;
                if (sum >= cars) {
                    break;
                }
            }
            if (sum >= cars) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }
}

