        int max_length = 0;
        for (int len : lengths) {
            if (len > max_length) {
                max_length = len;
            }
        }

        int result = 0;
        for (int i = 0; i < n; i++) {
            if (lengths[i] == max_length) {
                result += counts[i];
            }
        }

        return result;
    }
}

