            primes_seen = set()
            for i in range(n):
                if is_prime[nums[i]]:
                    primes_seen.add(nums[i])
                prefix[i] = len(primes_seen)

            # Compute suffix counts
            suffix = [0] * n
            primes_seen = set()
            for i in range(n-1, -1, -1):
                if is_prime[nums[i]]:
                    primes_seen.add(nums[i])
                suffix[i] = len(primes_seen)

