class LFUCache {
public:
    LFUCache(int capacity) : capacity(capacity), count(capacity + 1) {}

    int get(int key) {
        if (cache.find(key) == cache.end()) {
            return -1;
        }
        auto& node = cache[key];
        node.use++;
        updateFrequency(node);
        return node.value;
    }

    void put(int key, int value) {
        if (cache.find(key) == cache.end()) {
            if (cache.size() == capacity) {
                auto lfu = minFrequency();
                cache.erase(lfu.first);
                count[lfu.second]--;
            }
            cache[key] = {value, 1};
            count[1]++;
        } else {
            auto& node = cache[key];
            node.value = value;
            node.use++;
            updateFrequency(node);
        }
    }
private:
    int capacity;
    unordered_map<int, Node> cache;
    unordered_map<int, int> count;

    struct Node {
        int value;
        int use;
    };

    void updateFrequency(Node& node) {
        int oldFreq = node.use;
        node.use = 1;
        count[oldFreq]--;
        count[node.use]++;
