class Solution {
public:
    int getMaxRepetitions(string s1, int n1, string s2, int n2) {
        if (s1.empty() || s2.empty() || n1 == 0 || n2 == 0) {
            return 0;
        }
        int j = 0;
        int count = 0;
        int repeatCount = 0;
        vector<int> s1Index(s1.size() + 1, 0);
        vector<int> s2Count(s1.size() + 1, 0);
        for (int i = 1; i <= n1; ++i) {
            for (int k = 0; k < s1.size(); ++k) {
                if (s1[k] == s2[j]) {
                    j++;
                    if (j == s2.size()) {
                        count++;
                        j = 0;
                    }
                }
                s1Index[i] = k;
                s2Count[i] = count;
                if (s1Index[i] == s1Index[i - 1] && s2Count[i] == s2Count[i - 1]) {
                    int start = i - (s1Index[i] - s1Index[i - 1]);
                    int len = s1Index[i] - s1Index[start];
                    repeatCount = (n1 - start) / len;
                    count += repeatCount * (s2Count[i] - s2Count[start]);
                    j = s2Count[start + repeatCount * len] - s2Count[start];
                    break;
                }
            }
        }
        return count / n2;
    }
};

