    bool dfs(int u, int c, vector<vector<int>>& adj, vector<int>& color) {
        color[u] = c;
        for (int v : adj[u]) {
            if (color[v] == -1) {
                if (!dfs(v, 1 - c, adj, color)) {
                    return false;
                }
            } else if (color[v] == c) {
                return false;
            }
        }
        return true;
    }
};

