        int nonRepeatingPart = 0;
        int repeatingPart = 0;
        bool decimalFound = false;
        bool repeatingFound = false;

        while (i < s.size() && s[i] != '.') {
            integerPart = integerPart * 10 + (s[i] - '0');
            i++;
        }

        if (i == s.size()) {
            return (double)integerPart;
        }

        i++;
        while (i < s.size() && s[i] != '(') {
            nonRepeatingPart = nonRepeatingPart * 10 + (s[i] - '0');
            i++;
        }

        if (i == s.size()) {
            return (double)integerPart + (double)nonRepeatingPart / pow(10, nonRepeatingPart.length());
        }

        i++;
        while (i < s.size() && s[i] != ')') {
            repeatingPart = repeatingPart * 10 + (s[i] - '0');
            i++;
        }

        return (double)integerPart + (double)nonRepeatingPart / pow(10, nonRepeatingPart.length()) + (double)repeatingPart / (pow(10, repeatingPart.length()) * (pow(10, repeatingPart.length()) - 1));
    }
};

