        int currentDay = 1;
        int currentWeight = 0;
        for (int weight : weights) {
            if (currentWeight + weight > capacity) {
                currentDay++;
                currentWeight = weight;
            } else {
                currentWeight += weight;
            }
            if (currentDay > days) {
                return false;
            }
        }
        return true;
    }
}

