    public int palindromePartition(String s, int k) {
        int n = s.length();
        int[][] dp = new int[k][n];
        for (int i = 0; i < k; i++) {
            Arrays.fill(dp[i], Integer.MAX_VALUE);
        }
        dp[0][0] = 0;
        for (int i = 1; i < k; i++) {
            for (int j = i; j < n; j++) {
                if (isPalindrome(s, j - i + 1, j)) {
                    dp[i][j] = Math.min(dp[i][j], dp[i - 1][j - 1] + 1);
