class SeatManager {

    private int[] seats;
    private int nextAvailable;

    public SeatManager(int n) {
        seats = new int[n + 1];
        nextAvailable = 1;
        Arrays.fill(seats, 1);
    }

    public int reserve() {
        int seat = nextAvailable;
        nextAvailable++;
        return seat;
    }

    public void unreserve(int seatNumber) {
        seats[seatNumber] = 1;
    }
}

