                if (answerKey.charAt(left) == 'T') {
                    trueCount--;
                } else {
                    falseCount--;
                }
                left++;
            }
            maxFalse = Math.max(maxFalse, right - left + 1);
            right++;
        }
        return Math.max(maxTrue, maxFalse);
    }
}

