class RangeModule {

    private List<Range> ranges;

    public RangeModule() {
        ranges = new ArrayList<>();
    }

    public void addRange(int left, int right) {
        int i = 0;
        while (i < ranges.size()) {
            Range r = ranges.get(i);
            if (right <= r.left) {
                ranges.add(i, new Range(left, right));
                return;
            } else if (left >= r.right) {
                i++;
            } else {
                left = Math.min(left, r.left);
                right = Math.max(right, r.right);
                ranges.set(i, new Range(left, right));
                return;
            }
        }
        ranges.add(new Range(left, right));
    }

    public boolean queryRange(int left, int right) {
        for (Range r : ranges) {
            if (left < r.right && right > r.left) {
                return true;
            }
        }
        return false;
    }

    public void removeRange(int left, int right) {
        List<Range> newRanges = new ArrayList<>();
        for (Range r : ranges) {
            if (left < r.right && right > r.left) {
                if (left < r.left) {
                    newRanges.add(new Range(r.left, right));
                }
                if (right > r.right) {
                    newRanges.add(new Range(right, r.right));
                }
            } else {
                newRanges.add(r);
            }
        }
        ranges = newRanges;
    }
}

class Range {
    int left;
    int right;

    public Range(int left, int right) {
        this.left = left;
        this.right = right;
    }
}

