class Solution:
    def longestSemiRepetitiveSubstring(self, s: str) -> int:
        n = len(s)
        dp = [[0 for _ in range(n)] for _ in range(n)]
        for i in range(n):
            dp[i][i] = 1
        for i in range(n - 1):
            if s[i] != s[i + 1]:
                dp[i][i + 1] = 2
        for k in range(3, n + 1):
            for i in range(n - k + 1):
                j = i + k - 1
