class Solution {
public:
    int palindromePartition(string s, int k) {
        int n = s.size();
        vector<vector<int>> dp(n, vector<int>(n, 0));
        for (int i = 0; i < n; i++) {
            dp[i][i] = 0;
            for (int j = i + 1; j < n; j++) {
                if (s[i] == s[j]) {
                    dp[i][j] = dp[i + 1][j - 1];
                } else {
                    dp[i][j] = dp[i + 1][j - 1] + 1;
                }
            }
        }
        int ans = INT_MAX;
        function<void(int, int)> dfs = [&](int l, int r) {
            if (r - l + 1 == k) {
                ans = min(ans, dp[l][r]);
                return;
            }
            for (int i = l; i <= r; i++) {
                if (i - l >= k - 1) {
                    dfs(l, i - 1);
                    dfs(i + 1, r);
                    return;
                }
            }
        };
        dfs(0, n - 1);
        return ans;
    }
};

