                int cnt = 0;
                for (int i = 0; i < d; i++) {
                    int j = i;
                    while (j < n) {
                        if (s[j] != s[j - i]) cnt++;
                        j += d;
                    }
                }
                res = min(res, cnt);
            }
        }
        return res;
    }
};

