        newNode->val = val;
        newNode->next = head;
        if (head != nullptr) head->prev = newNode;
        head = newNode;
        if (tail == nullptr) tail = newNode;
        size++;
    }

    void addAtTail(int val) {
        Node* newNode = new Node();
        newNode->val = val;
        newNode->prev = tail;
        if (tail != nullptr) tail->next = newNode;
        tail = newNode;
        if (head == nullptr) head = newNode;
        size++;
    }

