            graph[path[1] - 1][path[0] - 1] = true;
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 4; j++) {
                if (!graph[i][j]) {
                    answer[i] = j + 1;
                    for (int k = 0; k < n; k++) {
                        if (graph[k][j]) {
                            graph[k][answer[i] - 1] = true;
                        }
                    }
                    break;
                }
            }
        }
