class Solution {
    public int getMinSwaps(String num, int k) {
        int n = num.length();
        int[] count = new int[10];
        for (char c : num.toCharArray()) {
            count[c - '0']++;
        }
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = num.charAt(i) - '0';
        }
        int res = 0;
        for (int i = 0; i < n; i++) {
            if (i + count[arr[i]] - 1 < n - 1) {
                int j = i;
                while (j < n - 1 && arr[j] == arr[i]) {
                    j++;
                }
                int temp = arr[i];
                for (int p = i; p < j; p++) {
                    arr[p] = arr[p + 1];
                }
                arr[j] = temp;
                res += j - i;
            }
        }
        int[] sorted = new int[n];
        for (int i = 0; i < n; i++) {
