        next[0] = 0;
        for (int i = 1; i <= n; i++) {
            next[i] = next[i - 1] + (sorted[i - 1] != sorted[i - 2] ? 1 : 0);
        }
        int[] dp = new int[n + 1];
        for (int i = 0; i <= n; i++) {
