class Solution {
    public long findMaximumNumber(long k, int x) {
        long num = 1;
        while (true) {
            long price = 0;
            long temp = num;
            while (temp > 0) {
                price += (temp & 1);
                temp >>= 1;
                temp *= x;
            }
            if (price * (num + 1) / 2 > k) {
                return num - 1;
            }
            num++;
        }
    }
}

