class Solution {
    public String resultingString(String s) {
        while (s.length() > 1) {
            StringBuilder sb = new StringBuilder();
            boolean found = false;
            for (int i = 0; i < s.length() - 1; i++) {
                if (Math.abs(s.charAt(i) - s.charAt(i + 1)) == 1 || Math.abs(s.charAt(i) - s.charAt(i + 1)) == 25) {
