        TreeNode root = new TreeNode(Integer.parseInt(nodes[0]));
        nodes = Arrays.copyOfRange(nodes, 1, nodes.length);
        root.left = deserializeHelper(nodes);
        root.right = deserializeHelper(nodes);
        return root;
    }
}

