        int i = idx / n;
        int j = idx % n;
        row[i]++;
        col[j]++;
        return new int[] { i, j };
    }

    public void reset() {
        count = m * n;
        Arrays.fill(row, 0);
        Arrays.fill(col, 0);
    }
}

