    public int minimumDeleteSum(String s1, String s2) {
        int m = s1.length(), n = s2.length();
        int[][] dp = new int[m + 1][n + 1];
        for (int i = 0; i <= m; i++) {
            dp[i][0] = i == 0 ? 0 : dp[i - 1][0] + s1.charAt(i - 1);
        }
        for (int j = 0; j <= n; j++) {
            dp[0][j] = j == 0 ? 0 : dp[0][j - 1] + s2.charAt(j - 1);
        }
        for (int i = 1; i <= m; i++) {
