                if (time >= start && time <= end) {
                    count++;
                }
            }
            result.add(count);
            start += chunkSize;
        }
        return result;
    }

    private int getChunkSize(String freq) {
        switch (freq) {
            case "minute":
                return 60;
            case "hour":
                return 3600;
            case "day":
                return 86400;
            default:
                throw new IllegalArgumentException("Invalid frequency");
        }
    }
}

