        char c = s.charAt(0);
        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) != c) {
                return false;
            }
        }
        return true;
    }

    private int countOccurrences(String s, String substr) {
        int count = 0;
        int idx = s.indexOf(substr);
        while (idx != -1) {
            count++;
            idx = s.indexOf(substr, idx + 1);
        }
        return count;
    }
}

