    public int minChanges(int n, int k) {
        int changes = 0;
        while (n != 0 && k != 0) {
            int nBit = n & 1;
            int kBit = k & 1;
            if (nBit == 1 && kBit == 0) {
                changes++;
            }
            n >>= 1;
            k >>= 1;
        }
        if (n == 0 && k == 0) {
            return changes;
        } else if (n == 0) {
            return -1;
