            NestedInteger top = stack.pop();
            if (top.isInteger()) {
                return top.getInteger();
            } else {
                for (int i = top.getList().size() - 1; i >= 0; i--) {
                    stack.push(top.getList().get(i));
                }
            }
        }
        return null;
    }
