        for (char c : s.toCharArray()) {
            count[c - 'a']++;
        }
        int[] digits = new int[10];
        digits[0] = count[24]; // z
        digits[2] = count[20]; // w
        digits[4] = count[5]; // u
        digits[6] = count[23]; // x
