        StringBuilder result = new StringBuilder();
        while (!stack.isEmpty()) {
            char c = stack.pop();
            if (c == '(') {
                while (stack.peek() != ')') {
                    result.append(stack.pop());
                }
                stack.pop(); // remove ')'
                for (int i = 0; i < result.length(); i++) {
                    stack.push(result.charAt(result.length() - 1 - i));
                }
                result.setLength(0);
            } else {
                result.append(c);
            }
        }
        return result.toString();
    }
}

