class Solution {
    public int maxTaskAssign(int[] tasks, int[] workers, int pills, int strength) {
        Arrays.sort(tasks);
        Arrays.sort(workers);
        int i = tasks.length - 1, j = workers.length - 1, res = 0;
        while (i >= 0 && j >= 0) {
            if (workers[j] + pills * strength >= tasks[i]) {
                res++;
                i--;
                j--;
                pills--;
            } else {
                j--;
            }
        }
        return res;
    }
}

