public:
    string solveEquation(string equation) {
        int left = 0, right = equation.find('=');
        string leftEq = equation.substr(0, right), rightEq = equation.substr(right + 1);
        int leftX = 0, leftNum = 0, rightX = 0, rightNum = 0;
