            if (isdigit(leftEq[i])) {
                leftNum += (leftEq[i] - '0');
            } else if (leftEq[i] == 'x') {
                leftX++;
            } else if (leftEq[i] == '+') {
                continue;
            } else {
                leftNum -= (leftEq[i] - '0');
            }
        }
        for (int i = 0; i < rightEq.size(); i++) {
            if (isdigit(rightEq[i])) {
                rightNum += (rightEq[i] - '0');
            } else if (rightEq[i] == 'x') {
                rightX++;
            } else if (rightEq[i] == '+') {
                continue;
            } else {
                rightNum -= (rightEq[i] - '0');
            }
        }
        if (leftX == rightX) {
            if (leftNum == rightNum) {
                return "Infinite solutions";
            } else {
                return "No solution";
            }
        } else {
            int res = (rightNum - leftNum) / (leftX - rightX);
            return "x=" + to_string(res);
        }
    }
