public:
    string countOfAtoms(string formula) {
        stack<pair<string, int>> st;
        map<string, int> mp;
        int i = 0;
        while (i < formula.size()) {
            if (formula[i] == '(') {
                st.push({ "", 0 });
                i++;
            } else if (formula[i] == ')') {
                string s = st.top().first;
                int c = st.top().second;
                st.pop();
                i++;
                while (i < formula.size() && isdigit(formula[i])) {
                    c = c * 10 + (formula[i] - '0');
                    i++;
                }
                for (auto &p : mp) {
                    p.second += p.second / c;
                }
                mp = map<string, int>();
                for (auto &p : st) {
                    p.second *= c;
                }
