class Solution {
    public int shipWithinDays(int[] weights, int days) {
        int left = 0, right = (int)1e5;
        while (left < right) {
            int mid = left + (right - left) / 2;
            int cur = 0, cnt = 1;
            for (int w : weights) {
                cur += w;
                if (cur > mid) {
                    cur = w;
                    cnt++;
                }
            }
            if (cnt > days) {
