        for (int i = 0; i <= maxRow; i++) {
            if (seats[i].length >= k) {
                for (int j = 0; j < seats[i].length - k + 1; j++) {
                    if (seats[i][j] == 1) {
                        for (int l = 0; l < k; l++) {
                            seats[i][j + l] = 0;
                        }
                        return true;
                    }
                }
            }
        }
        return false;
    }
}

