            if (grumpy[i - minutes] == 1) {
                extraSatisfied -= customers[i - minutes];
            }
            maxExtraSatisfied = max(maxExtraSatisfied, extraSatisfied);
        }
        return totalSatisfied + maxExtraSatisfied;
    }
