            if (node.second == inDegree[node.first] + 1) {
                start = node.first;
                break;
            }
        }

        vector<vector<int>> result;
        function<void(int)> dfs = [&](int node) {
            while (!graph[node].empty()) {
                int next = graph[node].back();
                graph[node].pop_back();
                dfs(next);
                result.push_back({node, next});
            }
        };

        dfs(start);
        reverse(result.begin(), result.end());
        return result;
    }
};

