class Solution {
public:
    int numberOfWays(int n, int x) {
        vector<int> nums;
        int i = 1;
        while (pow(i, x) <= n) {
            nums.push_back(pow(i, x));
            i++;
        }
        vector<int> dp(n + 1, 0);
        dp[0] = 1;
        for (int num : nums) {
            for (int j = n; j >= num; j--) {
                dp[j] = (dp[j] + dp[j - num]) % (int)(1e9 + 7);
            }
        }
        return dp[n];
    }
};
