    string minWindow(string s, string t) {
        if (s.size() < t.size()) return "";

        unordered_map<char, int> tCount;
        for (char c : t) tCount[c]++;

        int required = tCount.size();
        int formed = 0;

        unordered_map<char, int> windowCounts;
