                windowCounts[leftChar]--;

                if (tCount.find(leftChar) != tCount.end() && windowCounts[leftChar] < tCount[leftChar]) {
                    formed--;
                }

                windowStart++;
            }
        }

        return minLength == INT_MAX ? "" : s.substr(minStart, minLength);
    }
};

