class Solution {
    public int maxValue(int n, int index, int maxSum) {
        int left = index, right = index;
        int sum = 1;
        maxSum -= n;
        int maxVal = 1;
        while (maxSum > 0) {
            maxVal++;
            if (left > 0) left--;
            if (right < n - 1) right++;
            sum += (right - left + 1);
            maxSum -= sum;
        }
        return maxSum < 0 ? maxVal - 1 : maxVal;
    }
}
