class Solution {
    public int minSwaps(int[] nums) {
        int n = nums.length;
        int totalOnes = 0;
        for (int num : nums) {
            totalOnes += num;
        }
        int minSwaps = n;
        int onesInWindow = 0;
        for (int i = 0; i < totalOnes; i++) {
            onesInWindow += nums[i];
        }
        minSwaps = Math.min(minSwaps, totalOnes - onesInWindow);
        for (int i = totalOnes; i < n + totalOnes; i++) {
            onesInWindow += nums[i % n] - nums[(i - totalOnes) % n];
            minSwaps = Math.min(minSwaps, totalOnes - onesInWindow);
        }
        return minSwaps;
    }
}

