                    case '*':
                        stack[top - 1] *= currNum;
                        break;
                    case '/':
                        stack[top - 1] /= currNum;
                        break;
                }
                operation = s.charAt(i);
                currNum = 0;
            }
        }

        int result = 0;
        while (top > 0) {
            result += stack[--top];
        }
        return result;
    }
