class Solution {
    public int longestSubsequence(String s, int k) {
        int countZero = 0;
        for (char c : s.toCharArray()) {
            if (c == '0') countZero++;
        }
        int n = s.length();
        long val = k;
        int count = 0;
        for (int i = 0; i < 32; i++) {
            if ((val & (1L << i)) != 0) {
                count = i;
                break;
            }
        }
        if (count >= n) return countZero + n;
        int ans = countZero + count;
        for (int i = n - 1; i >= 0 && count >= 0; i--) {
            if (s.charAt(i) == '1') {
                count--;
                ans++;
            }
        }
        return ans;
    }
}
