        int[] firstUpper = new int[26];
        boolean[] seenLower = new boolean[26];
        int count = 0;

        for (int i = 0; i < word.length(); i++) {
            char c = word.charAt(i);
            int index = c - 'a';

            if (Character.isLowerCase(c)) {
                seenLower[index] = true;
            } else {
                if (firstUpper[index] == 0) {
                    firstUpper[index] = i + 1;
                }
            }
