                for (int j = 0; j < word.length(); j++) {
                    char c = word.charAt(j);
                    int index = c - 'a';
                    if (Character.isLowerCase(c) && index == i && j >= firstUpper[i] - 1) {
                        count--;
                        break;
                    }
                }
                count++;
            }
        }
        return count;
    }
}

