class Solution {
    public char kthCharacter(long k, int[] operations) {
        long length = 1;
        int shift = 0;
        for (int op : operations) {
            length *= 2;
            if (op == 1) shift++;
        }
        while (k > 0) {
            if (k > length / 2) {
                k -= length / 2;
                shift++;
            }
            length /= 2;
        }
        return (char) ('a' + (shift - 1) % 26);
    }
}
