class Solution {
    public double minTime(int n, int k, int m, int[] time, double[] mul) {
        Arrays.sort(time);
        int maskCount = 1 << n;
        double[][] dp = new double[m][maskCount];
        for (double[] d : dp) {
            Arrays.fill(d, -1);
        }
        return dfs(0, (1 << n) - 1, n, k, m, time, mul, dp);
    }

    private double dfs(int stage, int mask, int n, int k, int m, int[] time, double[] mul, double[][] dp) {
        if (mask == 0) return 0;
        if (dp[stage][mask] != -1) return dp[stage][mask];
        double res = Double.MAX_VALUE;
        for (int i = 1; i <= k && i <= n; i++) {
            for (int subMask = mask; subMask > 0; subMask = (subMask - 1) & mask) {
                if (Integer.bitCount(subMask) == i) {
                    int maxTime = 0;
                    for (int j = 0; j < n; j++) {
                        if (((subMask >> j) & 1) == 1) maxTime = Math.max(maxTime, time[j]);
                    }
                    double crossTime = maxTime * mul[stage];
                    int nextStage = (stage + (int) crossTime) % m;
                    double returnTime = time[Integer.numberOfTrailingZeros(subMask)] * mul[nextStage];
                    int nextMask = mask ^ subMask;
                    double totalTime = crossTime + (i < n ? returnTime + dfs(nextStage, nextMask, n, k, m, time, mul, dp) : 0);
                    res = Math.min(res, totalTime);
                }
            }
        }
        return dp[stage][mask] = res;
    }
}

class Solution {
    public int maxStability(int n, int[][] edges, int k) {
        UnionFind uf = new UnionFind(n);
        for (int[] edge : edges) {
            if (edge[3] == 1) {
                if (!uf.union(edge[0], edge[1])) return -1;
            }
        }
        if (uf.getComponentCount() > 1 && k == 0) return -1;

        Arrays.sort(edges, (a, b) -> a[2] - b[2]);

        int lo = 0, hi = edges.length - 1;
        while (lo < hi) {
            int mid = lo + (hi - lo + 1) / 2;
            if (check(edges, mid, uf, n, k)) lo = mid;
            else hi = mid - 1;
        }

        return check(edges, lo, uf, n, k) ? edges[lo][2] : -1;
    }

    private boolean check(int[][] edges, int idx, UnionFind uf, int n, int k) {
        UnionFind tempUf = new UnionFind(n);
        for (int i = 0; i <= idx; i++) {
            if (edges[i][3] == 1) tempUf.union(edges[i][0], edges[i][1]);
            else if (k > 0) {
                tempUf.union(edges[i][0], edges[i][1]);
                k--;
            }
        }
        for (int[] edge : edges) {
            if (edge[3] == 1) {
                if (!tempUf.isConnected(edge[0], edge[1])) return false;
            }
        }
        return tempUf.getComponentCount() == 1;
    }
}

class UnionFind {
    private int[] parent;
    private int count;

    public UnionFind(int n) {
        parent = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
        }
        count = n;
    }

    public int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    public boolean union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX == rootY) return false;
        parent[rootY] = rootX;
        count--;
        return true;
    }

    public boolean isConnected(int x, int y) {
        return find(x) == find(y);
    }

    public int getComponentCount() {
        return count;
    }
}

