class Solution {
    public int minStable(int[] nums, int maxC) {
        int n = nums.length;
        int[] count = new int[n];
        for (int i = 0; i < n; i++) {
            if (nums[i] % 2 == 0) count[i] = 1;
            if (i > 0) count[i] += count[i - 1];
        }
        int maxLen = 0;
        for (int i = 0; i < n; i++) {
            int lo = i, hi = n - 1;
            while (lo <= hi) {
                int mid = lo + (hi - lo) / 2;
                if (check(nums, count, i, mid)) {
                    lo = mid + 1;
                } else {
                    hi = mid - 1;
                }
            }
            maxLen = Math.max(maxLen, hi - i + 1);
        }
        return Math.max(1, maxLen - maxC);
    }

    private boolean check(int[] nums, int[] count, int i, int j) {
        int evenCount = count[j];
        if (i > 0) evenCount -= count[i - 1];
        return evenCount <= (j - i + 1) / 2;
    }
}

class Solution {
    public int[] popcountDepth(long[] nums, long[][] queries) {
        int[] depthCount = new int[nums.length];
        for (int i = 0; i < nums.length; i++) {
            depthCount[i] = getPopcountDepth(nums[i]);
        }

        int[] answers = new int[queries.length];
        int j = 0;
        for (long[] query : queries) {
            if (query[0] == 1) {
                int count = 0;
                for (int i = (int) query[1]; i <= query[2]; i++) {
                    if (depthCount[i] == query[3]) {
                        count++;
                    }
                }
                answers[j++] = count;
            } else {
                int idx = (int) query[1];
                long val = query[2];
                depthCount[idx] = getPopcountDepth(val);
            }
        }
        return answers;
    }

    private int getPopcountDepth(long x) {
        int depth = 0;
        while (x != 1) {
            x = Long.bitCount(x);
            depth++;
        }
        return depth;
    }
}
