class AllOne {
    private static class Node {
        int count;
        Set<String> keys;
        Node prev;
        Node next;

        Node(int count) {
            this.count = count;
            this.keys = new HashSet<>();
        }
    }

    private final Map<String, Node> keyNodeMap;
    private final Node head;
    private final Node tail;

    public AllOne() {
        keyNodeMap = new HashMap<>();
        head = new Node(0);
        tail = new Node(Integer.MAX_VALUE);
        head.next = tail;
        tail.prev = head;
    }

    public void inc(String key) {
        Node node = keyNodeMap.get(key);
        if (node == null) {
            if (head.next.count != 1) {
                addNodeAfter(head, new Node(1));
            }
            head.next.keys.add(key);
            keyNodeMap.put(key, head.next);
        } else {
            if (node.next.count != node.count + 1) {
                addNodeAfter(node, new Node(node.count + 1));
            }
            node.next.keys.add(key);
            keyNodeMap.put(key, node.next);
            node.keys.remove(key);
            if (node.keys.isEmpty()) {
                removeNode(node);
            }
        }
    }

    public void dec(String key) {
        Node node = keyNodeMap.get(key);
        keyNodeMap.remove(key);
        node.keys.remove(key);
        if (node.prev.count != node.count - 1) {
            addNodeAfter(node.prev, new Node(node.count - 1));
        }
        node.prev.keys.add(key);
        keyNodeMap.put(key, node.prev);
        if (node.keys.isEmpty()) {
            removeNode(node);
        }
    }

    public String getMaxKey() {
        return tail.prev == head ? "" : tail.prev.keys.iterator().next();
    }

    public String getMinKey() {
        return head.next == tail ? "" : head.next.keys.iterator().next();
    }

    private void addNodeAfter(Node prev, Node newNode) {
        newNode.prev = prev;
        newNode.next = prev.next;
        prev.next.prev = newNode;
        prev.next = newNode;
    }

    private void removeNode(Node node) {
        node.prev.next = node.next;
        node.next.prev = node.prev;
    }
}

