        while (temp > 0) {
            digitCounts[temp % 10]++;
            temp /= 10;
        }
        while (num > 0) {
            int digit = num % 10;
            if (digitCounts[digit] != digit) {
                return false;
            }
            num /= 10;
        }
        return true;
    }
}

