class Solution {
    public List<Long> maximumEvenSplit(long finalSum) {
        List<Long> result = new ArrayList<>();
        if (finalSum % 2 != 0) return result;

        long i = 2;
        while (finalSum > 0) {
            if (finalSum - i < i) break;
            result.add(i);
            finalSum -= i;
            i += 2;
        }
        if (finalSum > 0) result.add(finalSum);
        return result;
    }
}

