            int dist = (curr - prev) / 2;
            if (dist > maxDist) {
                maxDist = dist;
                seat = prev + dist;
            }
            prev = curr;
        }

        int lastDist = n - 1 - prev;
        if (lastDist > maxDist) {
            seat = prev + lastDist;
        }

        seats.add(seat);
        return seat;
    }

    public void leave(int p) {
        seats.remove(p);
    }
}

