class Solution {
    public int leastOpsExpressTarget(int x, int target) {
        if (x == target) return 0;
        if (x > target) return 1;

        int ops = 0;
        while (x < target) {
            if ((target - x) % x == 0) {
                ops += (target - x) / x;
                return ops;
            }
            target += x;
            ops++;
        }
        return ops + 1;
    }
}

