class Solution:
    def findMaximumNumber(self, k: int, x: int) -> int:
        def count_set_bits(num):
            count = 0
            while num:
                count += num & 1
                num >>= 1
            return count

        def calculate_price(num, x):
            price = 0
            i = 1
            while num:
                if num & 1:
                    price += count_set_bits(i // x)
                i += 1
                num >>= 1
            return price

        left, right = 0, 10**15
        while left < right:
            mid = (left + right + 1) // 2
            accumulated_price = 0
            i = 1
            while i <= mid:
                accumulated_price += calculate_price(i, x)
                i += 1
            if accumulated_price <= k:
                left = mid
            else:
                right = mid - 1
        return left

