class Solution {
public:
    int palindromePartition(string s, int k) {
        int n = s.size();
        if (k == n) return 0;

        vector<vector<int>> cost(n, vector<int>(n, 0));
        for (int l = 2; l <= n; ++l) {
            for (int i = 0; i + l - 1 < n; ++i) {
                int j = i + l - 1;
                cost[i][j] = (s[i] != s[j]) + cost[i+1][j-1];
            }
        }

        vector<vector<int>> dp(k + 1, vector<int>(n, 1e9));
        for (int i = 0; i < n; ++i) dp[1][i] = cost[0][i];

        for (int p = 2; p <= k; ++p) {
            for (int j = p - 1; j < n; ++j) {
                for (int i = p - 2; i < j; ++i) {
                    dp[p][j] = min(dp[p][j], dp[p-1][i] + cost[i+1][j]);
                }
            }
        }
        return dp[k][n-1];
    }
};

