class Solution {
public:
    int numberOfArrays(string s, int k) {
        const int MOD = 1'000'000'007;
        int n = s.size();
        vector<int> dp(n + 1, 0);
        dp[n] = 1;

        for (int i = n - 1; i >= 0; --i) {
            if (s[i] == '0') {
                dp[i] = 0;
                continue;
            }
            long long num = 0;
            int ways = 0;
            for (int j = i; j < n; ++j) {
                num = num * 10 + (s[j] - '0');
                if (num > k) break;
                ways = (ways + dp[j + 1]) % MOD;
            }
            dp[i] = ways;
        }
        return dp[0];
    }
};

