class Solution {
public:
    int isPrefixOfWord(string sentence, string searchWord) {
        int idx = 1;
        size_t start = 0;
        size_t space;
        while (true) {
            space = sentence.find(' ', start);
            string word = sentence.substr(start, space - start);
            if (word.compare(0, searchWord.size(), searchWord) == 0) return idx;
            if (space == string::npos) break;
            start = space + 1;
            ++idx;
        }
        return -1;
    }
};

