class Solution {
public:
    int minDays(int n) {
        unordered_map<int,int> dp;
        dp[0] = 0;
        dp[1] = 1;
        return dfs(n, dp);
    }
private:
    int dfs(int n, unordered_map<int,int>& dp) {
        if (dp.count(n)) return dp[n];
        int ans = 1 + min(
            n % 2 + dfs(n/2, dp),
            n % 3 + dfs(n/3, dp)
        );
        dp[n] = ans;
        return ans;
    }
};

