class Solution {
public:
    int minChanges(vector<int>& nums, int k) {
        int n = nums.size();
        const int MAX = 1 << 10;
        vector<unordered_map<int, int>> freq(k);
        vector<int> total(k, 0);
        for (int i = 0; i < n; ++i) {
            int g = i % k;
            freq[g][nums[i]]++;
            total[g]++;
        }
        vector<int> dp(MAX, n);
        dp[0] = 0;
        for (int g = 0; g < k; ++g) {
            int min_prev = *min_element(dp.begin(), dp.end());
            vector<int> ndp(MAX, min_prev + total[g]);
            for (int x = 0; x < MAX; ++x) {
                for (const auto& [val, cnt] : freq[g]) {
                    int y = x ^ val;
                    ndp[x] = min(ndp[x], dp[y] + total[g] - cnt);
                }
            }
            dp = move(ndp);
        }
        return dp[0];
    }
};

