            prefix[0] = 0;
            for (int i = 0; i < n; ++i) {
                int val = nums[i];
                prefix[i + 1] = prefix[i];
                if (isPrime[val]) {
                    if (lastSeen[val] == -1) {
                        prefix[i + 1]++;
                    }
                    lastSeen[val] = i;
                }
            }
        };

        auto buildSuffix = [&]() {
            fill(lastSeen.begin(), lastSeen.end(), -1);
            suffix[n] = 0;
            for (int i = n - 1; i >= 0; --i) {
                int val = nums[i];
                suffix[i] = suffix[i + 1];
