    unordered_map<int, list<Node>::iterator> cntToNode;

public:
    AllOne() {}

    void inc(string key) {
        if (keyToNode.count(key)) {
            auto it = keyToNode[key];
            int oldCnt = it->cnt;
            int newCnt = oldCnt + 1;
            auto nextIt = next(it);
            if (nextIt == dll.end() || nextIt->cnt != newCnt) {
                nextIt = dll.insert(nextIt, Node(newCnt));
                cntToNode[newCnt] = nextIt;
            }
            nextIt->keys.insert(key);
            keyToNode[key] = nextIt;
            it->keys.erase(key);
            if (it->keys.empty()) {
                cntToNode.erase(oldCnt);
                dll.erase(it);
            }
        } else {
            if (dll.empty() || dll.front().cnt != 1) {
                dll.push_front(Node(1));
                cntToNode[1] = dll.begin();
            }
            dll.front().keys.insert(key);
            keyToNode[key] = dll.begin();
        }
    }

