                auto prevIt = dll.insert(it, Node(newCnt));
                cntToNode[newCnt] = prevIt;
            }
            auto prevIt = prev(it);
            prevIt->keys.insert(key);
            keyToNode[key] = prevIt;
        }
        it->keys.erase(key);
        if (it->keys.empty()) {
            cntToNode.erase(oldCnt);
            dll.erase(it);
        }
    }

