class Solution {
public:
    int findKthNumber(int n, int k) {
        auto count = [n](long prefix) -> long {
            long total = 0;
            long first = prefix;
            long last = prefix;
            while (first <= n) {
                total += last - first + 1;
                first *= 10;
                last = last * 10 + 9;
                if (last > n) last = n;
            }
            return total;
        };

        int cur = 1;
        k--;
        while (k > 0) {
            long c = count(cur);
            if (c <= k) {
                k -= c;
                cur++;
            } else {
                cur *= 10;
                k--;
            }
        }
        return cur;
    }
};

