class RangeModule {
    vector<pair<int,int>> ranges;
public:
    RangeModule() {}

    void addRange(int left, int right) {
        vector<pair<int,int>> newRanges;
        for (auto& p : ranges) {
            if (p.second < left) newRanges.push_back(p);
            else if (p.first > right) newRanges.push_back(p);
            else {
                left = min(left, p.first);
                right = max(right, p.second);
            }
        }
        newRanges.push_back({left, right});
        sort(newRanges.begin(), newRanges.end());
        ranges.swap(newRanges);
    }

    bool queryRange(int left, int right) {
        int l = 0, r = ranges.size() - 1;
        while (l <= r) {
            int m = l + (r - l) / 2;
            if (ranges[m].second <= left) l = m + 1;
            else if (ranges[m].first >= right) r = m - 1;
            else {
                if (ranges[m].first <= left && ranges[m].second >= right) return true;
                return false;
            }
        }
        return false;
    }

    void removeRange(int left, int right) {
        vector<pair<int,int>> newRanges;
        for (auto& p : ranges) {
            if (p.second <= left || p.first >= right) {
                newRanges.push_back(p);
            } else {
                if (p.first < left) newRanges.push_back({p.first, left});
                if (p.second > right) newRanges.push_back({right, p.second});
            }
        }
        ranges.swap(newRanges);
    }
};

