class Solution {
public:
    vector<vector<int>> combine(int n, int k) {
        vector<vector<int>> res;
        vector<int> cur;
        backtrack(1, n, k, cur, res);
        return res;
    }
private:
    void backtrack(int start, int n, int k, vector<int>& cur, vector<vector<int>>& res) {
        if (cur.size() == k) {
            res.push_back(cur);
            return;
        }
        for (int i = start; i <= n - (k - cur.size()) + 1; ++i) {
            cur.push_back(i);
            backtrack(i + 1, n, k, cur, res);
            cur.pop_back();
        }
    }
};

