class Solution {
    public int palindromePartition(String s, int k) {
        int n = s.length();
        if (k == n) return 0;
        int[][] cost = new int[n][n];
        for (int l = 1; l <= n; l++) {
            for (int i = 0; i + l - 1 < n; i++) {
                int j = i + l - 1;
                if (l == 1) cost[i][j] = 0;
                else cost[i][j] = (s.charAt(i) == s.charAt(j) ? 0 : 1) + cost[i + 1][j - 1];
            }
        }
        int[][] dp = new int[k + 1][n];
        for (int j = 0; j < n; j++) dp[1][j] = cost[0][j];
        for (int i = 2; i <= k; i++) {
            for (int j = i - 1; j < n; j++) {
                dp[i][j] = Integer.MAX_VALUE;
                for (int p = i - 2; p < j; p++) {
                    dp[i][j] = Math.min(dp[i][j], dp[i - 1][p] + cost[p + 1][j]);
                }
            }
        }
        return dp[k][n - 1];
    }
}

