        int[][] dp = new int[k + 1][n];
        for (int j = 0; j < n; j++) dp[1][j] = cost[0][j];
        for (int i = 2; i <= k; i++) {
            for (int j = i - 1; j < n; j++) {
                dp[i][j] = Integer.MAX_VALUE;
                for (int p = i - 2; p < j; p++) {
                    dp[i][j] = Math.min(dp[i][j], dp[i - 1][p] + cost[p + 1][j]);
                }
            }
        }
        return dp[k][n - 1];
    }
}

