class Solution {
    public int maxValue(int n, int index, int maxSum) {
        long left = 1, right = maxSum;
        while (left < right) {
            long mid = left + (right - left + 1) / 2;
            if (sum(n, index, mid) <= maxSum) {
                left = mid;
            } else {
                right = mid - 1;
            }
        }
        return (int) left;
    }

    private long sum(int n, int index, long val) {
        long leftLen = index;
        long rightLen = n - index - 1;
        return val + sumSide(val - 1, leftLen) + sumSide(val - 1, rightLen);
    }

    private long sumSide(long peak, long len) {
        if (len == 0) return 0;
        if (peak >= len) {
            return (peak + (peak - len + 1)) * len / 2;
        } else {
            return (peak * (peak + 1)) / 2 + (len - peak);
        }
    }
}

