class Solution {
    public int kIncreasing(int[] arr, int k) {
        int n = arr.length;
        int res = 0;
        for (int r = 0; r < k; r++) {
            List<Integer> seq = new ArrayList<>();
            for (int i = r; i < n; i += k) seq.add(arr[i]);
            res += seq.size() - lis(seq);
        }
        return res;
    }
    private int lis(List<Integer> nums) {
        List<Integer> tails = new ArrayList<>();
        for (int x : nums) {
            int idx = upperBound(tails, x);
            if (idx == tails.size()) tails.add(x);
            else tails.set(idx, x);
        }
        return tails.size();
    }
    private int upperBound(List<Integer> list, int key) {
        int lo = 0, hi = list.size();
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (list.get(mid) <= key) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
}

