class Solution {
    public int countDigitOne(int n) {
        int count = 0;
        for (long k = 1; k <= n; k *= 10) {
            long r = n / k;
            long m = r % 10;
            long l = r / 10;
            count += (int) (l * k);
            if (m > 1) {
                count += k;
            } else if (m == 1) {
                count += n % k + 1;
            }
        }
        return count;
    }
}

