class Solution {
    public long minSumSquareDiff(int[] nums1, int[] nums2, int k1, int k2) {
        int n = nums1.length;
        long[] diff = new long[n];
        for (int i = 0; i < n; ++i) {
            diff[i] = Math.abs(nums1[i] - nums2[i]);
        }
        long total = k1 + k2;
        long left = 0, right = 0;
        for (long d : diff) right = Math.max(right, d);
        long ans = right;
        while (left <= right) {
            long mid = left + (right - left) / 2;
            long needed = 0;
            for (long d : diff) {
                if (d > mid) needed += d - mid;
            }
            if (needed <= total) {
                ans = mid;
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        long res = 0;
        long rem = total;
        for (long d : diff) {
            if (d > ans) {
                rem -= (d - ans);
                res += ans * ans;
            } else {
                res += d * d;
            }
        }
        res -= rem * ans;
        return res;
    }
}

