        num = two;
        while (num > 0) {
            digits[idx++] = num % 10;
            num /= 10;
        }
        num = three;
        while (num > 0) {
            digits[idx++] = num % 10;
            num /= 10;
        }
        if (idx != 9) return false;
        for (int i = 0; i < 9; i++) {
            int d = digits[i];
            if (d == 0) return false;
            if ((mask & (1 << d)) != 0) return false;
            mask |= (1 << d);
        }
