class Solution {
    public int minimumOperationsToMakeEqual(int x, int y) {
        if (x == y) return 0;
        int[] dist = new int[10001];
        java.util.Arrays.fill(dist, Integer.MAX_VALUE);
        java.util.Deque<Integer> q = new java.util.ArrayDeque<>();
        q.offer(x);
        dist[x] = 0;
        while (!q.isEmpty()) {
            int cur = q.poll();
            if (cur == y) return dist[cur];
            int[] next = {cur - 1, cur + 1};
            for (int nxt : next) {
                if (nxt >= 1 && nxt <= 10000 && dist[nxt] > dist[cur] + 1) {
                    dist[nxt] = dist[cur] + 1;
                    q.offer(nxt);
                }
            }
            if (cur % 11 == 0) {
                int nxt = cur / 11;
                if (nxt >= 1 && nxt <= 10000 && dist[nxt] > dist[cur] + 1) {
                    dist[nxt] = dist[cur] + 1;
                    q.offer(nxt);
                }
            }
            if (cur % 5 == 0) {
                int nxt = cur / 5;
                if (nxt >= 1 && nxt <= 10000 && dist[nxt] > dist[cur] + 1) {
                    dist[nxt] = dist[cur] + 1;
                    q.offer(nxt);
                }
            }
        }
        return dist[y];
    }
}

