class Solution {
    public long[] unmarkedSumArray(int[] nums, int[][] queries) {
        int n = nums.length;
        int m = queries.length;
        long[] ans = new long[m];
        boolean[] marked = new boolean[n];
        long total = 0;
        for (int v : nums) total += v;

        int[][] arr = new int[n][2];
        for (int i = 0; i < n; i++) {
            arr[i][0] = nums[i];
            arr[i][1] = i;
        }
        Arrays.sort(arr, (a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]);

        int ptr = 0;
        for (int q = 0; q < m; q++) {
            int idx = queries[q][0];
            int k = queries[q][1];
            if (!marked[idx]) {
                marked[idx] = true;
                total -= nums[idx];
            }
            while (ptr < n && k > 0) {
                int val = arr[ptr][0];
                int i = arr[ptr][1];
                if (!marked[i]) {
                    marked[i] = true;
                    total -= val;
                    k--;
                }
                ptr++;
            }
            ans[q] = total;
        }
        return ans;
    }
}

