class Solution {
    public boolean isSubstringPresent(String s) {
        int n = s.length();
        if (n < 2) return false;
        boolean[] seen = new boolean[26 * 26];
        for (int i = 0; i < n - 1; ++i) {
            int key = (s.charAt(i) - 'a') * 26 + (s.charAt(i + 1) - 'a');
            seen[key] = true;
        }
        for (int i = 0; i < n - 1; ++i) {
            int key = (s.charAt(i + 1) - 'a') * 26 + (s.charAt(i) - 'a');
            if (seen[key]) return true;
        }
        return false;
    }
}

