class Solution {
    public long minEnd(int n, int x) {
        long m = n - 1;
        long mask = x;
        long bit = 1;
        while (m > 0) {
            if ((mask & bit) == 0) {
                mask |= (m & 1) * bit;
                m >>= 1;
            }
            bit <<= 1;
        }
        return mask;
    }
}

