class Solution {
    public int findNthDigit(int n) {
        int len = 1;
        long count = 9;
        long start = 1;

        while (n > len * count) {
            n -= len * count;
            len++;
            count *= 10;
            start *= 10;
        }

        start += (n - 1) / len;
        String numStr = Long.toString(start);
        return numStr.charAt((n - 1) % len) - '0';
    }
}

