class Solution {
    public int compress(char[] chars) {
        int n = chars.length;
        int write = 0;
        int read = 0;
        while (read < n) {
            char cur = chars[read];
            int count = 0;
            while (read < n && chars[read] == cur) {
                read++;
                count++;
            }
            chars[write++] = cur;
            if (count > 1) {
                for (char c : String.valueOf(count).toCharArray()) {
                    chars[write++] = c;
                }
            }
        }
        return write;
    }
}

