class Solution {
    public boolean canPartitionKSubsets(int[] nums, int k) {
        int total = 0;
        for (int num : nums) total += num;
        if (total % k != 0) return false;
        int target = total / k;
        Arrays.sort(nums);
        int n = nums.length;
        if (nums[n - 1] > target) return false;
        boolean[] used = new boolean[n];
        return dfs(nums, n - 1, target, k, 0, used);
    }
    private boolean dfs(int[] nums, int idx, int target, int k, int curr, boolean[] used) {
        if (k == 1) return true;
        if (curr == target) return dfs(nums, nums.length - 1, target, k - 1, 0, used);
        for (int i = idx; i >= 0; i--) {
            if (!used[i] && curr + nums[i] <= target) {
                used[i] = true;
                if (dfs(nums, i - 1, target, k, curr + nums[i], used)) return true;
                used[i] = false;
                if (curr == 0) break;
            }
        }
        return false;
    }
}

