class Solution {
    public int reachNumber(int target) {
        target = Math.abs(target);
        int k = 0;
        long sum = 0;
        while (sum < target) {
            k++;
            sum += k;
        }
        if ((sum - target) % 2 == 0) {
            return k;
        } else if ((sum + k + 1 - target) % 2 == 0) {
            return k + 1;
        } else {
            return k + 2;
        }
