class ExamRoom {
    private TreeSet<Integer> seats;
    private int n;

    public ExamRoom(int n) {
        this.n = n;
        this.seats = new TreeSet<>();
    }

    public int seat() {
        if (seats.isEmpty()) {
            seats.add(0);
            return 0;
        }
        int maxDist = seats.first();
        int pos = 0;
        Integer prev = null;
        for (int curr : seats) {
            if (prev != null) {
                int dist = (curr - prev) / 2;
                if (dist > maxDist) {
                    maxDist = dist;
                    pos = prev + dist;
                }
            }
            prev = curr;
        }
        int lastDist = (n - 1) - seats.last();
        if (lastDist > maxDist) {
            pos = n - 1;
        }
        seats.add(pos);
        return pos;
    }

    public void leave(int p) {
        seats.remove(p);
    }
}

