    public List<Integer> powerfulIntegers(int x, int y, int bound) {
        Set<Integer> set = new HashSet<>();
        int maxI = (x == 1) ? 0 : (int) (Math.log(bound) / Math.log(x)) + 1;
        int maxJ = (y == 1) ? 0 : (int) (Math.log(bound) / Math.log(y)) + 1;
        for (int i = 0; i <= maxI; i++) {
