            if (xi > bound) break;
            for (int j = 0; j <= maxJ; j++) {
                int yj = (int) Math.pow(y, j);
                int sum = xi + yj;
                if (sum <= bound) {
                    set.add(sum);
                } else {
                    break;
                }
            }
        }
        return new ArrayList<>(set);
    }
}

