class Solution:
    def maximumLength(self, s: str) -> int:
        runs = defaultdict(list)
        n = len(s)
        i = 0
        while i < n:
            c = s[i]
            j = i
            while j < n and s[j] == c:
                j += 1
            runs[c].append(j - i)
            i = j

        max_len = -1
        for c in runs:
            lengths = runs[c]
            lengths.sort(reverse=True)
            for L in range(min(lengths), 0, -1):
                cnt = 0
