class Solution:
    def possibleStringCount(self, word: str, k: int) -> int:
        MOD = 10**9 + 7

        # Build run-length encoding
        runs = []
        prev = None
        cnt = 0
        for ch in word:
            if ch == prev:
                cnt += 1
            else:
                if prev is not None:
                    runs.append(cnt)
                prev = ch
                cnt = 1
        if cnt:
            runs.append(cnt)
        m = len(runs)

        # DP[i][j] = ways to choose j characters from first i runs
        max_len = len(word)
        if max_len < k:
            return 0

        # Use 1D DP to save space
        dp = [0] * (max_len + 2)
        dp[0] = 1

        for run in runs:
            new_dp = dp[:]
            for j in range(max_len + 1):
                if dp[j]:
                    for take in range(1, run + 1):
                        if j + take <= max_len:
                            new_dp[j + take] = (new_dp[j + take] + dp[j]) % MOD
            dp = new_dp

        total = 0
        for l in range(k, max_len + 1):
            total = (total + dp[l]) % MOD
        return total

