        int left = 0;
        int zeros = 0;

        while (left < n && binary[left] == '1') {
            left++;
        }

        for (int i = left; i < n; ++i) {
            if (binary[i] == '0') {
                ++zeros;
            }
        }

        if (zeros <= 1) {
