                val *= i;
                if (val > n) break;
            }
            if (val > n) break;
            powers.push_back(val);
        }
        vector<int> dp(n + 1, 0);
        dp[0] = 1;
        for (auto num : powers) {
            for (int s = n; s >= num; --s) {
                dp[s] = (dp[s] + dp[s - num]) % MOD;
            }
        }
        return dp[n];
    }
};

