        if (n == 0) return 0;

        vector<vector<int>> dp(n, vector<int>(n, 0));

        for (int l = 1; l < n; ++l) {
            dp[l][l] = 1;
            for (int r = l + 1; r < n; ++r) {
                dp[l][r] = dp[l][r - 1] + 1;
                for (int k = l; k < r; ++k) {
