class Solution {
public:
    bool validPalindrome(string s) {
        auto isPalindrome = [&](int l, int r) {
            while (l < r) {
                if (s[l] != s[r]) return false;
                l++;
                r--;
            }
            return true;
        };

        int left = 0, right = s.length() - 1;
        while (left < right) {
            if (s[left] == s[right]) {
                left++;
                right--;
            } else {
                return isPalindrome(left + 1, right) || isPalindrome(left, right - 1);
            }
        }
        return true;
    }
};

