            if (inResult[idx]) {
                count[idx]--;
                continue;
            }
            while (!stack.isEmpty() && stack.peek() > c && count[stack.peek() - 'a'] > 0) {
                char top = stack.pop();
                inResult[top - 'a'] = false;
            }
            stack.push(c);
            inResult[idx] = true;
            count[idx]--;
        }
        StringBuilder sb = new StringBuilder();
        for (char c : stack) {
            sb.append(c);
        }
        return sb.toString();
    }
}

