class Solution {
    public int numberOfSubstrings(String s) {
        int n = s.length();
        int count = 0;
        int left = 0;
        int right = 0;
        int[] freq = new int[3];

        while (right < n) {
            freq[s.charAt(right) - 'a']++;

            while (freq[0] > 0 && freq[1] > 0 && freq[2'] > 0) {
                freq[s.charAt(left) - 'a']--;
                left++;
            }

            count += left;
            right++;
        }

        return count;
    }
}

