class Solution {
    public int[] maximumCount(int[] nums, int[][] queries) {
        int n = nums.length;
        int q = queries.length;
        int[] res = new int[q];
        int[] primeCountPrefix = new int[n];
        int[] primeCountSuffix = new int[n];
        int[] primeCount = new int[n];
        int[] primeSet = new int[100001];
        boolean[] isPrime = new boolean[100001];
        isPrime[2] = true;
        for (int i = 3; i < 100001; i++) {
            isPrime[i] = true;
        }
        for (int i = 2; i * i < 100001; i++) {
            if (isPrime[i]) {
                for (int j = i * i; j < 100001; j += i) {
                    isPrime[j] = false;
                }
            }
        }
        for (int i = 0; i < n; i++) {
            if (isPrime[nums[i]]) {
                primeSet[nums[i]]++;
            }
        }
        for (int i = 0; i < n; i++) {
            if (isPrime[nums[i]]) {
                primeCount[i] = 1;
            }
            if (i > 0) {
                primeCount[i] += primeCount[i - 1];
            }
        }
        for (int i = n - 1; i >= 0; i--) {
            if (isPrime[nums[i]]) {
                primeCountSuffix[i] = 1;
            }
            if (i < n - 1) {
                primeCountSuffix[i] += primeCountSuffix[i + 1];
            }
        }
        for (int i = 0; i < q; i++) {
            int idx = queries[i][0];
            int val = queries[i][1];
            if (isPrime[nums[idx]]) {
                primeSet[nums[idx]]--;
            }
            if (isPrime[val]) {
                primeSet[val]++;
            }
            nums[idx] = val;
            int max = 0;
            for (int k = 1; k < n; k++) {
                int left = 0;
                int right = 0;
                for (int j = 0; j < k; j++) {
                    if (isPrime[nums[j]]) {
                        left++;
                    }
                }
                for (int j = k; j < n; j++) {
                    if (isPrime[nums[j]]) {
                        right++;
                    }
                }
                max = Math.max(max, left + right);
            }
            res[i] = max;
        }
        return res;
    }
}

