                        counts[i] += counts[j];
                    }
                }
            }
        }

        int maxLen = 0;
        for (int l : lengths) {
            maxLen = Math.max(maxLen, l);
        }

        int res = 0;
        for (int i = 0; i < n; i++) {
            if (lengths[i] == maxLen) {
                res += counts[i];
            }
        }
        return res;
    }
