    def minEnd(self, n: int, x: int) -> int:
        bits = []
        i = 0
        while x:
            if x & 1:
                bits.append(i)
            x >>= 1
            i += 1

        res = 0
        for b in bits:
            res |= 1 << b

        mask = 0
        for b in bits:
