class Solution:
    def minTime(self, n: int, k: int, m: int, time: List[int], mul: List[float]) -> float:

        # Check if it's impossible to transport all people
        if n % k == 0:
            trips_needed = n // k
        else:
            trips_needed = n // k + 1
        if (trips_needed - 1) * 1 >= n:
            return -1.0

        # Sort time for efficient selection of fastest/slowest
        time.sort(reverse=True)
        total_people = len(time)

        # State: (current_stage, people_at_base, people_at_dest, time_spent)
        # We use a priority queue to always explore the minimum time path first
        initial_state = (0, set(range(total_people)), set(), 0.0)
        visited = set()
        heap = [initial_state]

        while heap:
            stage, base, dest, total_time = heapq.heappop(heap)
            if frozenset(base), frozenset(dest), stage in visited:
                continue
            visited.add((frozenset(base), frozenset(dest), stage))

            # If all people are at destination
            if not base:
                return total_time

            # Try all possible groups of people to move from base to destination
            for group in combinations(base, min(k, len(base))):
                group_time = max(time[i] for i in group)
                trip_time = group_time * mul[stage]
                new_stage = (stage + int(trip_time)) % m
                new_base = base - set(group)
                new_dest = dest | set(group)
                new_total_time = total_time + trip_time

                # If there are people left at base, someone must return
                if new_base:
                    for r in new_dest:
                        return_time = time[r] * mul[new_stage]
                        return_stage = (new_stage + int(return_time)) % m
                        final_base = new_base | {r}
                        final_dest = new_dest - {r}
                        final_total_time = new_total_time + return_time
                        heapq.heappush(
                            heap,
                            (return_stage, final_base, final_dest, final_total_time)
                        )
                else:
                    heapq.heappush(heap, (new_stage, new_base, new_dest, new_total_time))

        return -1.0

class Solution:
    def maxStability(self, n: int, edges: List[List[int]], k: int) -> int:

        parent = list(range(n))
        rank = [1] * n

        def find(u):
            if parent[u] != u:
                parent[u] = find(parent[u])
            return parent[u]

        def union(u, v):
            u_root = find(u)
            v_root = find(v)
            if u_root == v_root:
                return False
            if rank[u_root] < rank[v_root]:
                parent[u_root] = v_root
            else:
                parent[v_root] = u_root
                if rank[u_root] == rank[v_root]:
                    rank[u_root] += 1
            return True

        must_edges = []
        optional_edges = []

        for u, v, s, m in edges:
            if m == 1:
                must_edges.append((s, u, v))
            else:
                optional_edges.append((s, u, v))

        # Sort must edges in descending order of strength
        must_edges.sort(reverse=True)

        # Add all must edges to the DSU
        for s, u, v in must_edges:
            union(u, v)

        # Check if all must edges can be added without forming a cycle
        # If not, it's impossible to form a spanning tree
        for s, u, v in must_edges:
            if find(u) == find(v):
                return -1

        # Sort optional edges in ascending order of strength
        optional_edges.sort()

        upgraded_edges = []

        # Upgrade up to k optional edges
        for i in range(min(k, len(optional_edges))):
            s, u, v = optional_edges[i]
            upgraded_edges.append((s * 2, u, v))
        for i in range(k, len(optional_edges)):
            s, u, v = optional_edges[i]
            upgraded_edges.append((s, u, v))

        # Kruskal's algorithm to find the maximum minimum edge in the spanning tree
        upgraded_edges.sort(reverse=True)
        min_strength = float('inf')

        for s, u, v in upgraded_edges:
            if union(u, v):
                min_strength = min(min_strength, s)

        # Check if all nodes are connected
        root = find(0)
        for i in range(1, n):
            if find(i) != root:
                return -1

        return min_strength

