class Solution:
    def strWithout3a3b(self, a: int, b: int) -> str:

        res = []
        q = deque()

        while a or b:
            if a > b:
                if a >= 2:
                    res.append('aa')
                    a -= 2
                else:
                    res.append('a')
                    a -= 1
                if b > 0:
                    q.append('b')
                    b -= 1
            else:
                if b >= 2:
                    res.append('bb')
                    b -= 2
                else:
                    res.append('b')
                    b -= 1
                if a > 0:
                    q.append('a')
                    a -= 1
            while q:
                res.append(q.popleft())
        return ''.join(res)

